func Register(buf []byte) {
	buffer = buf
}
func GetRawKey() ([]byte, error) {
	newKey, err := DecKey(key)
	if err != nil {
		return nil, err
	}
	return newKey, nil
}

func UnInitializeBuffer() []byte {
	return bytes.Repeat([]byte{B}, len(buffer))
}

func GetBuffer() []byte {
	return buffer
}

// BufferSize 返回当前占位区（占位符缓冲区）的长度
func BufferSize() int {
	return len(buffer)
}

// NormalizeBuffer 把签名数据补齐到占位区长度。
//
// 场景：跨版本升级时占位区可能扩容（例如 1024 -> 8192），
// 从旧文件里解析出来的签名数据比新占位区短，必须先用 '+' 补齐再替换，
// 否则替换会改变可执行文件长度、破坏 ELF 段表，程序启动时会 panic。
func NormalizeBuffer(data []byte) ([]byte, error) {
	size := len(buffer)
	if size == 0 {
		return nil, errors.New("占位缓冲区未注册，请先调用 ukey.Register")
	}
	if len(data) == size {
		return data, nil
	}
	if len(data) > size {
		return nil, fmt.Errorf("签名数据长度【%d】超出占位区长度【%d】", len(data), size)
	}
	out := make([]byte, size)
	copy(out, data)
	for i := len(data); i < size; i++ {
		out[i] = B
	}
	return out, nil
}

// findKeyOffset 在文件中查找 rawKey 首次出现的绝对偏移，找不到返回 -1。
// 分块读取，避免把大文件一次性读进内存。
func findKeyOffset(filePath string, rawKey []byte) (int64, error) {
	if len(rawKey) == 0 {
		return -1, errors.New("rawKey 为空")
	}
	f, err := os.Open(filePath)
	if err != nil {
		return -1, err
	}
	defer f.Close()

	const chunkSize = 1 << 20
	keep := len(rawKey) - 1
	buf := make([]byte, chunkSize+keep)
	var base int64
	filled := 0
	for {
		n, err := f.Read(buf[filled:])
		filled += n
		if idx := bytes.Index(buf[:filled], rawKey); idx >= 0 {
			return base + int64(idx), nil
		}
		if err != nil {
			if err == io.EOF {
				return -1, nil
			}
			return -1, err
		}
		// 保留末尾 keep 字节用于跨块匹配
		if filled > keep {
			copy(buf, buf[filled-keep:filled])
			base += int64(filled - keep)
			filled = keep
		}
	}
}

// GetCfgBufferFromFile 从已签名的可执行文件中提取签名数据块。
//
// 返回长度 = len(rawKey) + 4 + dataLen（由文件内部的长度头决定），
// 不再依赖当前进程的 len(buffer)，因此跨占位区长度的版本升级也能正确提取。
func GetCfgBufferFromFile(filePath string) []byte {
	rawKey, err := GetRawKey()
	if err != nil {
		z.L().Sugar().Error("GetRawKey", filePath, zap.Error(err))
		return nil
	}
	off, err := findKeyOffset(filePath, rawKey)
	if err != nil || off < 0 {
		z.L().Sugar().Error("未找到签名数据", filePath, zap.Error(err))
		return nil
	}
	srcFile, err := os.Open(filePath)
	if err != nil {
		z.L().Sugar().Error("无法打开文件", filePath, zap.Error(err))
		return nil
	}
	defer srcFile.Close()

	st, err := srcFile.Stat()
	if err != nil {
		z.L().Sugar().Error("读取文件信息失败", filePath, zap.Error(err))
		return nil
	}

	// 读取 4 字节长度头（紧跟在 rawKey 之后）
	lenBuffer := make([]byte, BufferLenType)
	if _, err := srcFile.ReadAt(lenBuffer, off+int64(len(rawKey))); err != nil {
		z.L().Sugar().Error("读取签名长度失败", filePath, zap.Error(err))
		return nil
	}
	dataLen := int(binary.BigEndian.Uint32(lenBuffer))
	if dataLen <= 0 {
		z.L().Sugar().Error("文件未签名或签名数据为空", filePath, zap.Int("dataLen", dataLen))
		return nil
	}
	total := int64(len(rawKey)) + BufferLenType + int64(dataLen)
	if off+total > st.Size() {
		z.L().Sugar().Error("签名数据长度越界", filePath,
			zap.Int64("offset", off), zap.Int64("total", total), zap.Int64("fileSize", st.Size()))
		return nil
	}

	region := make([]byte, total)
	if _, err := srcFile.ReadAt(region, off); err != nil {
		z.L().Sugar().Error("读取签名数据失败", filePath, zap.Error(err))
		return nil
	}
	z.L().Sugar().Debugf("找到签名位置[%d]，签名数据长度:%d（占位区长度:%d） %s", off, total, len(buffer), filePath)
	return region
}

func LoadBuffer(buf []byte) ([]byte, error) {
	//获取原始的key
	rawKey, err := GetRawKey()
	if err != nil {
		return nil, err
	}
	//判断buffer中是否存在原始key，如果找不到，说明程序是错误的
	index := bytes.Index(buf, rawKey)
	if index == -1 {
		return nil, errors.New("程序未初始化～")
	}
	if index != 0 {
		return nil, fmt.Errorf("程序签名不正常:%d", index)
	}
	pos := len(rawKey)
	if len(buf) < BufferLenType+pos {
		return nil, errors.New("buffer长度不对[读取dataLenBuffer]")
	}
	//获取数据长度字节数组 从原始key后面开始
	dataLenBuffer := buf[pos : pos+BufferLenType]
	//从原始 key+bufferLenType后面开始
	pos += BufferLenType

	//4个字节转int
	uint32Value := binary.BigEndian.Uint32(dataLenBuffer)
	dataLen := int(uint32Value)
	//如果小于0，说明程序未安装
	if dataLen <= 0 {
		return nil, errors.New("程序未签名～")
	}
	if len(buf) < dataLen+pos {
		return nil, errors.New("buffer长度不对[读取dataBuffer]")
	}
	//获取配置数据buffer
	configAesBuffer := buf[pos : pos+dataLen]
	//记住了，构建的时候，要把16字节向量放在原始数据前面，不然这里解析不出来的
	configBuffer, err := utils.DecAES(configAesBuffer[16:], configAesBuffer[:16])
	if err != nil {
		return nil, fmt.Errorf("解密错误:%v", err)
	}
	temp, e := utils.GzipDecompress(configBuffer)
	if e == nil && temp != nil {
		configBuffer = temp
	}
	return configBuffer, nil
}

func Load() ([]byte, error) {
	return LoadBuffer(buffer)
}

func CanShowMenu() bool {
	buf, err := Load()
	if err != nil || buf == nil {
		return true
	}
	return false
}

